def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_x2(factors):
    # If x = p1^e1 * p2^e2 ..., then x^2 = p1^(2e1) * p2^(2e2) ...
    # tau(x^2) = (2e1 + 1) * (2e2 + 1) * ...
    tau = 1
    for exponent in factors.values():
        tau *= (2 * exponent + 1)
    return tau

candidates = [1680, 1440, 1260, 1080, 840]
results = {}

for x in candidates:
    factors = prime_factorization(x)
    tau = calculate_tau_x2(factors)
    results[x] = (factors, tau)

print("--- Results ---")
for x, (factors, tau) in results.items():
    print(f"x = {x} (Prime Factors: {factors}) -> Product (tau(x^2)): {tau}")

