import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    return divs

def calculate_N(x):
    """
    Calculates N(x), the number of positive integers y such that 1/x + 1/y is a unit fraction.
    N(x) = sum_{g | x} |{k' : 1 <= k' < x/g, gcd(x/g, k')=1, (x/g - k') | g}|
    """
    if x == 1:
        # N(1): 1/1 + 1/y = 1/k. 1 + 1/y = 1/k. 1/y = 1/k - 1. Since k>=1, 1/k <= 1. 1/k - 1 <= 0. 1/y > 0.
        # No solutions for y. N(1)=0.
        return 0

    divisors_g = get_divisors(x)
    N_x = 0

    for g in divisors_g:
        x_prime = x // g
        count_g = 0

        # Iterate over k' such that 1 <= k' < x'
        for k_prime in range(1, x_prime):
            # Condition 1: gcd(x', k') = 1
            if gcd(x_prime, k_prime) == 1:
                # Condition 2: (x' - k') must divide g
                m = x_prime - k_prime
                if g % m == 0:
                    count_g += 1

        N_x += count_g

    return N_x

candidates = [1680, 1260, 840, 1008, 720, 360]
results = {}
for x in candidates:
    results[x] = calculate_N(x)

print("Results N(x) for candidates:")
for x, n_x in results.items():
    print(f"N({x}) = {n_x}")

# Verification steps
max_N = 0
best_x = -1
for x, n_x in results.items():
    if n_x > max_N:
        max_N = n_x
        best_x = x

print(f"\nMaximum found among candidates: N({best_x}) = {max_N}")

